import{_ as a,o as t,c as i,a3 as o}from"./chunks/framework.D3oaa6bG.js";const v=JSON.parse('{"title":"Reviews","description":"","frontmatter":{},"headers":[],"relativePath":"guide/usage/reviews.md","filePath":"guide/usage/reviews.md","lastUpdated":null}'),s={name:"guide/usage/reviews.md"};function r(n,e,d,l,c,p){return t(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="reviews" tabindex="-1">Reviews <a class="header-anchor" href="#reviews" aria-label="Permalink to &quot;Reviews&quot;">​</a></h1><p>Reviews can be added for a Product or Variant.</p><p>A Review needs at least a star rating (1-5 stars). It can have an optional title and description as well as a list of pros and cons.</p><p>Reviews can be disabled completely via October&#39;s backend settings.</p><h2 id="review-categories" tabindex="-1">Review categories <a class="header-anchor" href="#review-categories" aria-label="Permalink to &quot;Review categories&quot;">​</a></h2><p>You can create additional review categories like <code>Price</code>, <code>Design</code> or <code>Build quality</code> and assign them to specific product categories.</p><p>This allows a customer to rate specific aspects of a product in more detail.</p><p>Review categories can be managed via the Product category edit form.</p><h2 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h2><p>The following settings can be configured in the backend:</p><h3 id="reviews-enabled" tabindex="-1">Reviews enabled <a class="header-anchor" href="#reviews-enabled" aria-label="Permalink to &quot;Reviews enabled&quot;">​</a></h3><p>This option removes the reviews form and list from the Product component if disabled.</p><h3 id="moderate-reviews" tabindex="-1">Moderate reviews <a class="header-anchor" href="#moderate-reviews" aria-label="Permalink to &quot;Moderate reviews&quot;">​</a></h3><p>If this option is enabled, reviews need to be approved by the site admin manually. Unapproved reviews are not visible on the website.</p><h3 id="allow-anonymous" tabindex="-1">Allow anonymous <a class="header-anchor" href="#allow-anonymous" aria-label="Permalink to &quot;Allow anonymous&quot;">​</a></h3><p>By default, only logged in customers can create reviews. If this option is enabled, everyone can review products.</p><h2 id="events" tabindex="-1">Events <a class="header-anchor" href="#events" aria-label="Permalink to &quot;Events&quot;">​</a></h2><p>See <a href="/wn-mall-plugin/development/core/events.html#Review">Events</a>.</p>',18)])])}const u=a(s,[["render",r]]);export{v as __pageData,u as default};
